import { expect, expectStatus, test } from "../../fixtures";

test("Submit a vendor with all documents extracted", { tag: "@REV-01" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorWithDocuments({ as: "member" });

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const submitted = await expectStatus(response, 200);
  expect(submitted.status).toBe("in_review");
  // Re-read the vendor: the status must be stored, not only echoed.
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");
  const audit = await expectStatus<{ items: { action: string }[] }>(
    await member.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  expect(audit.items.map((e) => e.action)).toContain("vendor.submitted");
});
